<template><div class="page"><div class="section-title"><div><div class="eyebrow">AUTONOMOUS OPERATIONS</div><h2>运维工作台</h2><span class="muted">自动发现、保守修复、人工故障排查的一体化控制台</span></div><n-button type="primary" :loading="store.loading" @click="store.refresh">刷新全局状态</n-button></div><div class="metric-grid"><div class="metric" v-for="m in metrics" :key="m.label"><n-icon :size="27" :color="m.color" :component="m.icon"/><div><div class="metric-value">{{m.value}}</div><div class="metric-label">{{m.label}}</div></div></div></div><div class="dashboard-grid"><div><section class="panel"><div class="section-title"><div><h3>活跃处置任务</h3><span class="muted">由 Background Supervisor 自动创建</span></div><router-link to="/app/background" class="link-button">查看任务中心 →</router-link></div><n-empty v-if="!store.alerts.length" description="当前没有待处理任务"/><n-list v-else hoverable><n-list-item v-for="a in store.alerts.slice(0,6)" :key="a.id" @click="openTask(a)"><div class="task-row"><n-tag :type="severityType(a.severity)" size="small">{{severityText(a.severity)}}</n-tag><div><strong>{{a.alert_name}}</strong><div class="muted">{{a.description||'正在等待后台分析'}}</div></div></div><n-tag size="small" :bordered="false">{{statusText(a.state)}}</n-tag></n-list-item></n-list></section><section class="panel"><div class="section-title"><div><h3>最近集群事件</h3><span class="muted">只读观测 autoops-test</span></div><router-link to="/app/cluster" class="link-button">打开观测台 →</router-link></div><n-empty v-if="!store.events.length" description="暂无 Events"/><n-list v-else><n-list-item v-for="e in store.events.slice(-5).reverse()" :key="`${e.object}-${e.timestamp}`"><div class="task-row"><n-tag :type="e.type==='Warning'?'warning':'info'" size="small">{{e.type}}</n-tag><div><strong>{{e.reason}} · {{e.object}}</strong><div class="muted">{{e.message}}</div></div></div></n-list-item></n-list></section></div><div><section class="panel health-card"><div class="section-title"><h3>集群健康摘要</h3><n-tag :type="store.summary?.healthy?'success':'error'">{{store.summary?.healthy?'稳定':'需要关注'}}</n-tag></div><div class="health-ring"><span>{{store.summary?.pods_ready||0}}/{{store.summary?.pods_total||0}}</span><small>Pods Ready</small></div><n-descriptions :column="1" size="small"><n-descriptions-item label="监测范围">{{store.summary?.namespace||'autoops-test'}}</n-descriptions-item><n-descriptions-item label="Deployment 可用">{{store.summary?.deployments_ready||0}} / {{store.summary?.deployments_total||0}}</n-descriptions-item><n-descriptions-item label="Warning Events">{{store.summary?.events_warning||0}}</n-descriptions-item></n-descriptions></section><section class="panel"><h3 style="margin-bottom:14px">快捷入口</h3><div class="quick-actions"><n-button secondary @click="router.push('/app/background')">查看自动处置</n-button><n-button secondary @click="router.push('/app/incidents')">进入故障排查</n-button><n-button secondary @click="router.push('/app/knowledge')">维护文档中心</n-button></div></section></div></div></div></template>
<script setup>import{computed}from'vue';import{useRouter}from'vue-router';import{useDashboardStore}from'@/stores/dashboard';import{WarningOutline,AlertCircleOutline,GitNetworkOutline,BookOutline,CheckmarkCircleOutline,BuildOutline}from'@vicons/ionicons5';const router=useRouter(),store=useDashboardStore();const metrics=computed(()=>[{label:'活跃处置',value:store.alerts.length,color:'#d99018',icon:WarningOutline},{label:'严重故障',value:store.critical,color:'#d03050',icon:AlertCircleOutline},{label:'待分析任务',value:store.warning,color:'#2080f0',icon:BuildOutline},{label:'异常 Pods',value:store.unhealthyPods,color:'#d03050',icon:GitNetworkOutline},{label:'健康 Deployment',value:`${store.summary?.deployments_ready||0}/${store.summary?.deployments_total||0}`,color:'#18a058',icon:CheckmarkCircleOutline},{label:'维护文档',value:store.documents.length,color:'#2080f0',icon:BookOutline}]);const severityText=s=>({simple:'简单',severe:'严重',critical:'严重',warning:'告警',unknown:'未知'}[s]||'未知'),severityType=s=>s==='simple'?'success':(s==='severe'||s==='critical'?'error':s==='warning'?'warning':'default'),statusText=s=>({received:'已接收',collecting_evidence:'采集证据',analyzing:'Agent 分析',policy_evaluating:'策略校验',auto_repairing:'自动修复',waiting_verification:'恢复验证',incident_created:'已转故障报告',waiting_human:'等待人工',resolved:'已恢复'}[s]||s);function openTask(a){router.push(a.incident_id?`/app/incidents/${a.incident_id}`:'/app/background')}</script>
